use super::{Arm, Line};

/// Locate the declaration of a binding known to be owned by a reaching JVM
/// local. Its exact spelling is generated by the lifter, not inferred from
/// Java source. A blank declaration is detached; an initializer stays at its
/// original evaluation site as an assignment.
pub(super) fn prove_local_relocation(
    lines: &[Line],
    arm: &Arm<'_, '_>,
    declaration: &str,
    name: &str,
    retarget: bool,
) -> Option<Vec<(usize, Option<usize>)>> {
    let body = &lines[arm.start..arm.end];
    let depth = body.iter()
        .filter(|line| !line.detached_declaration)
        .map(|line| line.depth)
        .min()?;
    let mut found = false;
    let mut sites = Vec::new();
    for (relative, line) in body.iter().enumerate() {
        if line.detached_declaration {
            continue;
        }
        let index = arm.start + relative;
        let text = line.text.as_flat();
        let suffix = text.strip_prefix(declaration);
        if let Some(rhs) = suffix.and_then(|text| text.strip_prefix(" = ")) {
            if found || line.depth != depth || (retarget && rhs.contains(name)) {
                return None;
            }
            found = true;
            sites.push((index, Some(declaration.len() + " = ".len())));
        } else if suffix == Some(";") {
            if found || line.depth != depth || !line.offsets.is_empty() || line.text.has_layout() {
                return None;
            }
            found = true;
            sites.push((index, None));
        } else if retarget {
            if let Some(rhs) = text.strip_prefix(name).and_then(|text| text.strip_prefix(" = ")) {
                if !found || rhs.contains(name) {
                    return None;
                }
                sites.push((index, Some(name.len() + " = ".len())));
            } else if text.contains(name) {
                // A read, capture, compound store, or even a coincidental
                // spelling in a literal is not a proved destination. Keep
                // the independent arm local and copy it on the merge edge.
                return None;
            }
        }
    }
    found.then_some(sites)
}
